import urllib.request
urls=['https://hgdownload.soe.ucsc.edu/goldenPath/hg38/bigZips/hg38.chrom.sizes','https://hgdownload.soe.ucsc.edu/goldenPath/hg38/bigZips/hg38.chrom.sizes.txt.gz']
for u in urls:
 try:
  data=urllib.request.urlopen(u,timeout=30).read(2000)
  print(u, data[:100], 'lenprefix', len(data))
 except Exception as e: print(e)
PY"

