/bin/bash -lc "python3 - <<'PY'
import os,json,urllib.request,urllib.error
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip(); url=os.environ['GALAXY_URL'].rstrip('/')
tool_id='toolshed.g2.bx.psu.edu/repos/iuc/bedtools/bedtools_coveragebed/2.31.1+galaxy0'
tss='f9cad7b01a47213591482517693cbd51'
files={'1':'f9cad7b01a472135b476504106c0f2ea','2':'f9cad7b01a4721358a60fb6fbe71a211','3':'f9cad7b01a4721357cdee678a0a8b7dd','4':'f9cad7b01a472135daa6e391b622b157','5':'f9cad7b01a47213528013fa71d18680c','6':'f9cad7b01a47213538f978bf8e6c8143','7':'f9cad7b01a4721356700416c5069c604','8':'f9cad7b01a4721355bd9ab6345db6a63','9':'f9cad7b01a472135d9388598dec4ebfa','10':'f9cad7b01a472135168f79d968c14504'}
results={}
for n,dsid in files.items():
 inputs={
  'inputA':{'src':'hda','id':tss},
  'reduce_or_iterate|reduce_or_iterate_selector':'iterate',
  'reduce_or_iterate|inputB':{'src':'hda','id':dsid},
  'split':False,'strandedness':False,'d':False,'hist':False,'mean':False,
  'overlap_a':'','overlap_b':'','reciprocal_overlap':False,'a_or_b':False,'sorted':False
 }
 payload=json.dumps({'history_id':'bbd44e69cb8906b56e15e753156354ed','tool_id':tool_id,'inputs':inputs}).encode()
 req=urllib.request.Request(url+'/api/tools',data=payload,headers={'x-api-key':key,'Content-Type':'application/json'},method='POST')
 try:
  with urllib.request.urlopen(req,timeout=60) as r:
   resp=json.loads(r.read()); results[n]={'job':resp['jobs'][0]['id'],'out':resp['outputs'][0]['id']}; print(n,results[n])
 except urllib.error.HTTPError as e: print(n,'ERR',e.code,e.read(1000).decode())
with open('/workspace/run_trace/tss_coverage_submissions.json','w') as f: json.dump(results,f,indent=2)
PY"

